// Convert Config sheet rows to an object keyed by 'key'.
const cfg = {};
for (const item of items) {
  const row = item.json;
  const key = String(row[0] || '').trim();
  const value = row[1];
  const type = String(row[2] || 'string').toLowerCase();
  let val = value;
  if (type === 'number') val = Number(value);
  else if (type === 'boolean') val = (String(value).toLowerCase() === 'true');
  else if (type === 'array' || type === 'csv') {
    if (Array.isArray(value)) val = value;
    else val = String(value || '').split(',').map(v => v.trim()).filter(Boolean);
  }
  else val = String(value);
  if (key) cfg[key] = val;
}
return [ { json: { config: cfg } } ];

// Combine config and job sources into items.
const config = $items('Config to Object')[0].json.config;
const rows = items;
const out = [];
// Skip header row (assume first row contains column names)
for (let i = 1; i < rows.length; i++) {
  const row = rows[i].json;
  const jobSource = {
    platform: row[0],
    token: row[1],
    company: row[2],
    active: String(row[3]).toLowerCase() === 'true',
    priority: Number(row[4] || 0),
    baseUrl: row[5],
    allowedRoles: row[6]
  };
  if (!jobSource.active) continue;
  out.push({ json: { config, jobSource } });
}
return out;

/*
 * Fetch jobs from ATS sources defined in the input items.
 * Input items should have { config, jobSource } in json.
 * Returns a list of job objects with normalized fields.
 */
async function fetchJobsForSource(jobSource) {
  const source = jobSource.platform ? jobSource.platform.toLowerCase() : '';
  const token = jobSource.token;
  let jobs = [];
  try {
    if (source === 'greenhouse') {
      const url = `https://boards-api.greenhouse.io/v1/boards/${token}/jobs?content=true`;
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url
      });
      jobs = response.jobs || [];
    } else if (source === 'lever') {
      const url = `https://api.lever.co/v0/postings/${token}?mode=json`;
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url
      });
      jobs = response || [];
    } else if (source === 'ashby') {
      const url = `https://api.ashbyhq.com/posting-api/job-board/${token}`;
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url
      });
      jobs = response.jobs || response || [];
    } else if (source === 'recruitee') {
      const url = `https://api.recruitee.com/careers/${jobSource.company}`;
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url,
        headers: {
          Authorization: `Bearer ${token}`
        }
      });
      jobs = response.jobs || response || [];
    }
  } catch (e) {
    jobs = [];
  }
  return jobs.map(job => ({ source: source, raw: job }));
}
function toISO(value) {
  try { return new Date(value).toISOString(); } catch (e) { return null; }
}
function b64(s) { return Buffer.from(String(s)).toString('base64').slice(0, 22); }
const output = [];
for (const item of items) {
  const jobSource = item.json.jobSource;
  const jobs = await fetchJobsForSource(jobSource);
  for (const entry of jobs) {
    const job = entry.raw;
    const title = job.title || job.text || job.name || '';
    const company = job.company || jobSource.company || '';
    const url = job.absolute_url || job.applyUrl || job.url || job.hostedUrl || '';
    const location = (job.location && (job.location.name || job.location)) || (job.offices && job.offices.map(o => o.name).join(', ')) || '';
    const postedAt = toISO(job.updated_at || job.created_at || job.createdAt || job.posted_at || job.createdDate);
    const descriptionRaw = job.content || job.description || job.details || '';
    const id = job.id || job._id || b64(`${company}|${title}|${url}`);
    const hash = b64(`${company}|${title}|${url}`);
    output.push({ json: {
      source: entry.source,
      id,
      hash,
      title,
      company,
      location,
      url,
      postedAt,
      descriptionRaw,
      config: item.json.config
    } });
  }
}
return output;

// Clean job descriptions, extract salary, remote and US flags
function stripHtml(html) { return String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); }
const US_STATES = ['AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY'];
function isUS(loc, text) { const s = `${loc} ${text}`.toLowerCase(); if (s.includes('united states') || / usa | us /.test(s)) return true; return US_STATES.some(ab => new RegExp(`\b${ab}\b`).test(loc)); }
function isRemote(loc, text) { const s = `${loc} ${text}`.toLowerCase(); return /(remote|work from home|anywhere in the u\.s\.|u\.s\. remote|distributed)/.test(s); }
function parseCompensation(text) { const s = String(text).replace(/[ \s]/g,' '); let min=null,max=null,curr='USD'; let m = s.match(/\$?\s*([\d]{2,3}(?:,\d{3})?)(?:\s*[-to]+\s*\$?\s*([\d]{2,3}(?:,\d{3})?))\s*(k|K)?\s*(?:per\s*year|annual|yr|year)?/); if (m) { const a = Number(m[1].replace(/,/g,'')); const b = m[2] ? Number(m[2].replace(/,/g,'')) : null; const mult = m[3] ? 1000 : 1; min = a*mult; max = b? b*mult : null; } else { const h = s.match(/(\d{2,3})\s*[kK]\s*(?:[-to]+\s*(\d{2,3})\s*[kK])?/); if (h) { min = Number(h[1])*1000; max = h[2] ? Number(h[2])*1000 : null; } } return { compMin:min, compMax:max, currency:curr }; }
return items.map(item => { const text = stripHtml(item.json.descriptionRaw); const comp = parseCompensation(text); const loc = item.json.location || ''; const remoteFlag = isRemote(loc, text); const isUSFlag = isUS(loc, text); return { json: { ...item.json, description: text, remoteFlag, isUS: isUSFlag, compMin: comp.compMin, compMax: comp.compMax, currency: comp.currency } }; });

// Apply filtering and simple scoring based on config.
const results = [];
for (const item of items) {
  const cfg = item.json.config || {};
  const title = (item.json.title || '').toLowerCase();
  const minSalary = Number(cfg.MIN_SALARY || cfg.min_salary_usd || 0);
  const titleRegexStr = cfg.TITLE_REGEX || cfg.title_regex || 'director|vp|head|customer success';
  const titleRe = new RegExp(titleRegexStr, 'i');
  const bannedTerms = (cfg.BLACKLIST_CC || cfg.banned_terms_csv || []);
  // Hard filters
  if (!titleRe.test(title)) continue;
  if (cfg.REMOTE_ONLY && !item.json.remoteFlag) continue;
  if (cfg.US_ONLY && !item.json.isUS) continue;
  if (Array.isArray(bannedTerms) && bannedTerms.some(term => title.includes(String(term).toLowerCase()))) continue;
  if (minSalary && item.json.compMin && item.json.compMin < minSalary) continue;
  // Simple heuristic score
  let score = 50;
  if (/director|vp|head/.test(title)) score += 20;
  if (item.json.remoteFlag) score += 10;
  if (item.json.compMin && item.json.compMin >= minSalary) score += 10;
  if (cfg.PREFERRED_C && typeof cfg.PREFERRED_C === 'object') {
    const preferred = Object.keys(cfg.PREFERRED_C).map(k => k.toLowerCase());
    if (preferred.includes((item.json.company || '').toLowerCase())) score += 10;
  }
  item.json.fitScore = score;
  results.push(item);
}
return results;

// Filter incoming jobs against seen hashes and prepare rows for Matches and Seen.
const seenRows = $items('Read Seen')[0].json;
const seenHashes = new Set();
if (Array.isArray(seenRows)) {
  for (let i = 1; i < seenRows.length; i++) {
    const row = seenRows[i];
    if (row && row[0]) seenHashes.add(row[0]);
  }
}
const newMatches = [];
const newSeen = [];
const notifications = [];
for (const item of items) {
  const hash = item.json.hash;
  if (seenHashes.has(hash)) continue;
  // Append to matches
  newMatches.push([
    hash,
    item.json.source,
    item.json.company,
    item.json.title,
    item.json.location,
    item.json.url,
    item.json.compMin || '',
    item.json.compMax || '',
    item.json.currency || '',
    item.json.postedAt || '',
    item.json.fitScore || '',
    ''
  ]);
  // Append to seen
  const now = new Date().toISOString();
  newSeen.push([hash, now, now, item.json.url]);
  // Notification data
  notifications.push(item.json);
}
return [ { json: { matches: newMatches, seen: newSeen, notifications } } ];

// Send notifications via configured channels.
            if (!items.length) return items;
            const all = items[0].json;
